using Conan.PluginApi;
using System;using System.IO;using System.IO.Packaging;using System.Linq;using System.Collections.Generic;using System.Reflection;using System.Security.Cryptography;using System.Text.RegularExpressions;using System.Web.Script.Serialization;using System.Net;
public class PluginManifest {
 public int ApiVersion=1;public string Id,Version,Name,Description,EntryAssembly,EntryType;
 public List<string> Capabilities=new List<string>();public Dictionary<string,string> Files=new Dictionary<string,string>();
}
public class PluginChoice {public string Id,Version;public bool Enabled;}
public class PluginProfile {public List<PluginChoice> Installed=new List<PluginChoice>();}
public class PluginRow {public PluginManifest Manifest;public bool Enabled,Running,RestartRequired;public string Error;}
public sealed class PluginManager:IDisposable {
 const long Maximum=128L*1024*1024;readonly object gate=new object();readonly string root,statePath;
 readonly JavaScriptSerializer json=new JavaScriptSerializer();PluginProfile profile;public string ProfileError{get;private set;}public string BootstrapStatus{get;private set;}
 readonly Dictionary<string,IConanPlugin> running=new Dictionary<string,IConanPlugin>();
 readonly Dictionary<string,string> loaded=new Dictionary<string,string>(),errors=new Dictionary<string,string>();
 readonly Dictionary<string,string> loadedHashes=new Dictionary<string,string>();
 readonly Dictionary<string,Type> loadedTypes=new Dictionary<string,Type>();
 public event Action Changed;
 public PluginManager(string dataFolder){root=Path.Combine(dataFolder,"plugins");statePath=Path.Combine(root,"plugins.json");try{Directory.CreateDirectory(root);profile=File.Exists(statePath)?json.Deserialize<PluginProfile>(File.ReadAllText(statePath)):new PluginProfile();if(profile==null||profile.Installed==null||profile.Installed.Any(c=>c==null||!Regex.IsMatch(c.Id??"","^[a-z][a-z0-9-]{2,39}$")||!Regex.IsMatch(c.Version??"",@"^[0-9]+(?:\.[0-9]+){1,3}$"))||profile.Installed.Select(c=>c.Id).Distinct(StringComparer.OrdinalIgnoreCase).Count()!=profile.Installed.Count)throw new InvalidDataException("插件登记格式无效。");}catch(Exception e){if(!(e is IOException)&&!(e is InvalidDataException)&&!(e is UnauthorizedAccessException)&&!(e is ArgumentException)&&!(e is InvalidOperationException)&&!(e is FormatException))throw;profile=new PluginProfile();ProfileError="插件登记无法读取；原文件已保留。";}}
 public bool HasProfile{get{return File.Exists(statePath);}}
 public bool BootstrapMonitor(string packageFile,string expectedHash,bool hasLegacySettings){if(!hasLegacySettings||HasProfile||ProfileError!=null||!File.Exists(packageFile))return false;try{if(new FileInfo(packageFile).Length>Maximum||Hash(File.ReadAllBytes(packageFile))!=expectedHash)throw new InvalidDataException("随附监控包校验失败。");if(Inspect(packageFile).Id!="system-monitor")throw new InvalidDataException("随附包标识不匹配。");Install(packageFile);SetEnabled("system-monitor",true);BootstrapStatus="已恢复原有系统监控。";return true;}catch(Exception e){if(!(e is IOException)&&!(e is InvalidDataException)&&!(e is UnauthorizedAccessException)&&!(e is ArgumentException)&&!(e is InvalidOperationException)&&!(e is FormatException))throw;BootstrapStatus="原有系统监控未能自动恢复："+e.Message;return false;}}
 public bool UpgradeBundledMonitor(string packageFile,string expectedHash){lock(gate){var choice=profile.Installed.FirstOrDefault(x=>x.Id=="system-monitor"&&x.Version=="1.0.0");if(choice==null||ProfileError!=null||!File.Exists(packageFile))return false;bool enabled=choice.Enabled;try{var old=Read(choice);if(old.EntryType!="Conan.Plugins.SystemMonitor.NativeTelemetry")return false;foreach(var file in old.Files){string path=Path.Combine(Folder(choice),file.Key.Replace('/',Path.DirectorySeparatorChar));if(!File.Exists(path)||Hash(File.ReadAllBytes(path))!=file.Value)throw new InvalidDataException("已安装的监控插件校验失败。");}if(new FileInfo(packageFile).Length>Maximum||Hash(File.ReadAllBytes(packageFile))!=expectedHash)throw new InvalidDataException("随附监控插件校验失败。");var newer=Inspect(packageFile);if(newer.Id!="system-monitor"||newer.Version!="1.0.1"||newer.EntryType!=old.EntryType)throw new InvalidDataException("随附监控插件版本不匹配。");Install(packageFile);try{SetEnabled("system-monitor",enabled);}catch{choice.Version="1.0.0";choice.Enabled=enabled;Save();throw;}BootstrapStatus="系统监控已更新，原启用状态和数据已保留。";return true;}catch(Exception e){if(!(e is IOException)&&!(e is InvalidDataException)&&!(e is UnauthorizedAccessException)&&!(e is ArgumentException)&&!(e is InvalidOperationException)&&!(e is FormatException))throw;BootstrapStatus="系统监控未能自动更新："+e.Message;return false;}}}
 public bool BootstrapLegacyPackage(string packageFile,string expectedHash,string expectedId,bool firstUpgrade){if(!firstUpgrade||ProfileError!=null||!File.Exists(packageFile))return false;try{if(new FileInfo(packageFile).Length>Maximum||Hash(File.ReadAllBytes(packageFile))!=expectedHash||Inspect(packageFile).Id!=expectedId)throw new InvalidDataException("随附插件包校验失败。");Install(packageFile);SetEnabled(expectedId,true);return true;}catch(Exception e){if(!(e is IOException)&&!(e is InvalidDataException)&&!(e is UnauthorizedAccessException)&&!(e is ArgumentException)&&!(e is InvalidOperationException)&&!(e is FormatException))throw;BootstrapStatus="原有功能未能自动恢复："+e.Message;return false;}}
 public bool BootstrapAddedFeature(string packageFile,string expectedHash,string id,bool existingUser){if(!existingUser||ProfileError!=null||!Regex.IsMatch(id??"","^[a-z][a-z0-9-]{2,39}$"))return false;string marker=Path.Combine(root,"migration-"+id+".done");if(File.Exists(marker))return false;try{if(!List().Any(x=>x.Manifest.Id==id)){if(!File.Exists(packageFile)||new FileInfo(packageFile).Length>Maximum||Hash(File.ReadAllBytes(packageFile))!=expectedHash||Inspect(packageFile).Id!=id)throw new InvalidDataException("随附插件包校验失败。");Install(packageFile);SetEnabled(id,true);}File.WriteAllText(marker,"1");return true;}catch(Exception e){if(!(e is IOException)&&!(e is InvalidDataException)&&!(e is UnauthorizedAccessException)&&!(e is ArgumentException)&&!(e is InvalidOperationException)&&!(e is FormatException))throw;BootstrapStatus="原有功能未能自动恢复："+e.Message;return false;}}
 internal static bool SafePath(string name){return !String.IsNullOrEmpty(name)&&name.Length<180&&!Path.IsPathRooted(name)&&!name.Contains("\\")&&!name.Contains(":")&&name.Split('/').All(s=>s.Length>0&&s!="."&&s!=".."&&!s.EndsWith(".")&&!s.EndsWith(" ")&&s.IndexOfAny(Path.GetInvalidFileNameChars())<0);}
 public static string Hash(byte[] data){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(data)).Replace("-","").ToLowerInvariant();}
 static void Validate(PluginManifest m){Version version;if(m==null||m.ApiVersion!=1||!Regex.IsMatch(m.Id??"","^[a-z][a-z0-9-]{2,39}$")||!Regex.IsMatch(m.Version??"",@"^[0-9]+(?:\.[0-9]+){1,3}$")||!Version.TryParse(m.Version,out version)||version.Major<1||String.IsNullOrWhiteSpace(m.Name)||m.Name.Length>80||m.Description==null||m.Description.Length>2000||m.Capabilities==null||m.Capabilities.Count>16||m.Capabilities.Any(x=>x==null||x.Length>160)||m.Files==null||m.Files.Count<1||m.Files.Count>64||!SafePath(m.EntryAssembly)||!m.EntryAssembly.EndsWith(".dll",StringComparison.OrdinalIgnoreCase)||String.IsNullOrWhiteSpace(m.EntryType)||!m.Files.ContainsKey(m.EntryAssembly)||m.Files.Any(p=>!SafePath(p.Key)||!Regex.IsMatch(p.Value??"","^[a-f0-9]{64}$")))throw new InvalidDataException("插件清单、接口版本或文件路径无效。");if(m.Files.Keys.Distinct(StringComparer.OrdinalIgnoreCase).Count()!=m.Files.Count)throw new InvalidDataException("插件包含大小写冲突的文件路径。");}
 string Folder(PluginChoice c){return Path.Combine(root,"installed",c.Id,c.Version);}
 void EnsureWritable(){if(ProfileError!=null)throw new InvalidOperationException(ProfileError);}
 void Save(){EnsureWritable();string temp=statePath+".tmp";File.WriteAllText(temp,json.Serialize(profile));if(File.Exists(statePath))File.Replace(temp,statePath,null);else File.Move(temp,statePath);}
 void Notify(){var changed=Changed;if(changed!=null)changed();}
 public static PluginManifest Inspect(string packageFile){if(new FileInfo(packageFile).Length>Maximum)throw new InvalidDataException("插件包超过128MiB。");using(var package=Package.Open(packageFile,FileMode.Open,FileAccess.Read)){var uri=new Uri("/manifest.json",UriKind.Relative);if(!package.PartExists(uri))throw new InvalidDataException("缺少插件清单。");var part=package.GetPart(uri);using(var input=part.GetStream())using(var reader=new StreamReader(input)){var characters=new char[65537];int length=reader.ReadBlock(characters,0,characters.Length);if(length>65536)throw new InvalidDataException("插件清单过大。");string text=new string(characters,0,length);var result=new JavaScriptSerializer().Deserialize<PluginManifest>(text);Validate(result);return result;}}}
 public void Install(string packageFile){
  EnsureWritable();var m=Inspect(packageFile);string stage=Path.Combine(root,"stage-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(stage);
  try{using(var package=Package.Open(packageFile,FileMode.Open,FileAccess.Read)){var names=package.GetParts().Select(p=>p.Uri.OriginalString.TrimStart('/')).ToArray();if(names.Length!=m.Files.Count+1||!names.Contains("manifest.json")||names.Any(n=>n!="manifest.json"&&!m.Files.ContainsKey(n)))throw new InvalidDataException("包内文件与清单不一致。");long total=0;
    foreach(var entry in m.Files){var part=package.GetPart(new Uri("/"+entry.Key,UriKind.Relative));byte[] bytes;using(var input=part.GetStream())using(var memory=new MemoryStream()){var buffer=new byte[65536];int count;while((count=input.Read(buffer,0,buffer.Length))>0){total+=count;if(total>Maximum)throw new InvalidDataException("解压内容超过128MiB。");memory.Write(buffer,0,count);}bytes=memory.ToArray();}if(Hash(bytes)!=entry.Value)throw new InvalidDataException("插件文件校验失败："+entry.Key);string path=Path.Combine(stage,entry.Key.Replace('/',Path.DirectorySeparatorChar));Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllBytes(path,bytes);}
   }
   File.WriteAllText(Path.Combine(stage,"manifest.json"),json.Serialize(m));lock(gate){var old=profile.Installed.FirstOrDefault(c=>c.Id==m.Id);string oldVersion=old==null?null:old.Version;bool oldEnabled=old!=null&&old.Enabled;string destination=Folder(new PluginChoice{Id=m.Id,Version=m.Version});if(Directory.Exists(destination))throw new InvalidOperationException("这个插件版本已经安装。");Directory.CreateDirectory(Path.GetDirectoryName(destination));Directory.Move(stage,destination);try{if(old!=null){Stop(m.Id);old.Version=m.Version;old.Enabled=false;}else profile.Installed.Add(new PluginChoice{Id=m.Id,Version=m.Version});Save();}catch{if(old!=null){old.Version=oldVersion;old.Enabled=oldEnabled;}else profile.Installed.RemoveAll(c=>c.Id==m.Id);Directory.Delete(destination,true);throw;}}Notify();
  }finally{if(Directory.Exists(stage))Directory.Delete(stage,true);}
 }
 PluginManifest Read(PluginChoice c){if(!Regex.IsMatch(c.Id??"","^[a-z][a-z0-9-]{2,39}$")||!Regex.IsMatch(c.Version??"",@"^[0-9]+(?:\.[0-9]+){1,3}$"))throw new InvalidDataException("插件登记路径无效。");var m=json.Deserialize<PluginManifest>(File.ReadAllText(Path.Combine(Folder(c),"manifest.json")));Validate(m);if(m.Id!=c.Id||m.Version!=c.Version)throw new InvalidDataException("插件登记与清单不一致。");return m;}
 public PluginRow[] List(){lock(gate)return profile.Installed.Select(c=>{try{var m=Read(c);return new PluginRow{Manifest=m,Enabled=c.Enabled,Running=running.ContainsKey(c.Id),RestartRequired=false,Error=errors.ContainsKey(c.Id)?errors[c.Id]:""};}catch(Exception e){return new PluginRow{Manifest=new PluginManifest{Id=c.Id,Version=c.Version,Name=c.Id},Error=e.Message};}}).ToArray();}
 public bool Enabled(string id){lock(gate){var c=profile.Installed.FirstOrDefault(x=>x.Id==id);return c!=null&&c.Enabled;}}
 public void SetEnabled(string id,bool enabled){lock(gate){var c=profile.Installed.FirstOrDefault(x=>x.Id==id);if(c==null)throw new InvalidOperationException("插件未安装。");bool previous=c.Enabled;c.Enabled=enabled;try{Save();}catch{c.Enabled=previous;throw;}if(!enabled)Stop(id);else errors.Remove(id);}Notify();}
 void Stop(string id){IConanPlugin value;if(running.TryGetValue(id,out value)){running.Remove(id);try{value.Dispose();}catch(Exception e){errors[id]="插件停用异常："+e.GetBaseException().Message;}}}
 public T Service<T>(string id)where T:class,IConanPlugin {lock(gate){var c=profile.Installed.FirstOrDefault(x=>x.Id==id);if(c==null||!c.Enabled||errors.ContainsKey(id))return null;IConanPlugin value;if(running.TryGetValue(id,out value))return value as T;
   try{var m=Read(c);foreach(var f in m.Files){string path=Path.Combine(Folder(c),f.Key.Replace('/',Path.DirectorySeparatorChar));if(!File.Exists(path)||Hash(File.ReadAllBytes(path))!=f.Value)throw new InvalidDataException("插件文件被修改，已停止加载。");}
    Type type;if(!loadedTypes.TryGetValue(id,out type)||!loaded.ContainsKey(id)||loaded[id]!=c.Version||loadedHashes[id]!=m.Files[m.EntryAssembly]){var assembly=Assembly.Load(File.ReadAllBytes(Path.Combine(Folder(c),m.EntryAssembly.Replace('/',Path.DirectorySeparatorChar))));type=assembly.GetType(m.EntryType,true);}if(!typeof(T).IsAssignableFrom(type)||type.IsAbstract)throw new InvalidDataException("插件服务接口不匹配。");value=(IConanPlugin)Activator.CreateInstance(type);if(value.Id!=id){value.Dispose();throw new InvalidDataException("插件标识不匹配。");}try{value.Initialize(new PluginContext{InstallDirectory=Folder(c),DataDirectory=Path.Combine(root,"data",id)});}catch{try{value.Dispose();}catch{}throw;}loaded[id]=c.Version;loadedHashes[id]=m.Files[m.EntryAssembly];loadedTypes[id]=type;running[id]=value;return value as T;
   }catch(Exception e){errors[id]="插件加载失败："+e.GetBaseException().Message;return null;}
  }}
 public void ReportFailure(string id,Exception error){lock(gate){Stop(id);errors[id]="插件运行失败："+error.GetBaseException().Message;}}
 public R Invoke<T,R>(string id,Func<T,R> action,R unavailable)where T:class,IConanPlugin {lock(gate){var service=Service<T>(id);if(service==null)return unavailable;try{return action(service);}catch(Exception e){ReportFailure(id,e);return unavailable;}}}
 public void Uninstall(string id){if(!Regex.IsMatch(id??"","^[a-z][a-z0-9-]{2,39}$"))throw new ArgumentException("插件标识无效。");lock(gate){var c=profile.Installed.FirstOrDefault(x=>x.Id==id);if(c==null)return;c.Enabled=false;Stop(id);Save();Directory.Delete(Path.Combine(root,"installed",id),true);profile.Installed.Remove(c);errors.Remove(id);Save();}Notify();}
 public static void Download(string url,string destination){Download(url,destination,null);}
 public static void Download(string url,string destination,Action<long,long?> progress){
  Uri uri;if(!Uri.TryCreate(url,UriKind.Absolute,out uri))throw new ArgumentException("请输入HTTPS下载链接。");
  ServicePointManager.SecurityProtocol|=SecurityProtocolType.Tls12;
  for(int redirect=0;redirect<=5;redirect++){
   if(uri.Scheme!="https"||!String.IsNullOrEmpty(uri.UserInfo))throw new ArgumentException("插件下载仅接受HTTPS链接。");
   var request=(HttpWebRequest)WebRequest.Create(uri);request.AllowAutoRedirect=false;request.Timeout=30000;request.ReadWriteTimeout=30000;
   using(var response=(HttpWebResponse)request.GetResponse()){
    int code=(int)response.StatusCode;
    if(new[]{301,302,303,307,308}.Contains(code)){string location=response.Headers["Location"];if(String.IsNullOrEmpty(location))throw new IOException("下载重定向没有目标地址。");uri=new Uri(uri,location);continue;}
    if(response.StatusCode!=HttpStatusCode.OK)throw new IOException("下载未返回完整插件包。");
    if(response.ContentLength>Maximum)throw new IOException("下载超过128MiB。");
    using(var input=response.GetResponseStream())using(var output=new FileStream(destination,FileMode.CreateNew)){byte[] bytes=new byte[65536];long total=0;long? length=response.ContentLength>=0?(long?)response.ContentLength:null;int count;if(progress!=null)progress(0,length);while((count=input.Read(bytes,0,bytes.Length))>0){total+=count;if(total>Maximum)throw new IOException("下载超过128MiB。");output.Write(bytes,0,count);if(progress!=null)progress(total,length);}if(length.HasValue&&total!=length.Value)throw new IOException("下载不完整。");}
    return;
   }
  }
  throw new IOException("下载重定向次数过多。");
 }
 public void Dispose(){lock(gate){foreach(var id in running.Keys.ToArray())Stop(id);}}
}
